  name String

  /// Short category description used to provide context in the storefront.
  description String

  /// URL-safe identifier for the category, used for stable links and routing.
  slug String

  /// Controls customer browsing visibility for this category (e.g., active vs
  /// hidden).
  visibility String

  /// Ordering value used to sort categories within the same parent scope.
  display_order Int @db.Integer

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

