    first.pagination.current,
  );
  TestValidator.equals(
    "consistent limit",
    second.pagination.limit,
    first.pagination.limit,
  );
  for (const item of second.data) {
    TestValidator.equals(
      "active wishlist must have deleted_at null",
      item.deleted_at,
      null,
    );
  }
}

