  const page2 = 2 satisfies number & tags.Type<"int32"> & tags.Minimum<1>;
  // Execute page 1
  const response1 = await api.functional.shoppingMall.member.wishlists.index(
    memberConnection,
    {
      body: { page: page1, limit } satisfies IShoppingMallWishlist.IRequest,
    },
  );
