export async function test_api_cart_delete_recomputes_state_and_enforces_ownership(
  connection: api.IConnection,
): Promise<void> {
  // =====================
  // Scenario 1: delete within same cart
  // =====================
  const memberAConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IShoppingMallMember.IJoin,
  });
  const cartA = await generate_random_shopping_mall_member_carts_create(
    memberAConnection,
    {},
  );
  typia.assert(cartA);
  const cartAItem1 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberAConnection,
      { params: { cartId: cartA.id } },
    );
  typia.assert(cartAItem1);
  const cartAItem2 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberAConnection,
      { params: { cartId: cartA.id } },
    );
  typia.assert(cartAItem2);
  const cartABefore = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cartA.id },
  );
  typia.assert(cartABefore);
  const item1Before = await api.functional.shoppingMall.member.carts.items.at(
    memberAConnection,
    { cartId: cartA.id, cartItemId: cartAItem1.id },
  );
  typia.assert(item1Before);
  const item2Before = await api.functional.shoppingMall.member.carts.items.at(
    memberAConnection,
    { cartId: cartA.id, cartItemId: cartAItem2.id },
  );
  typia.assert(item2Before);
  const warningBefore = cartABefore.warning_inventory_insufficient;
  await api.functional.shoppingMall.member.carts.items.erase(
    memberAConnection,
    { cartId: cartA.id, cartItemId: cartAItem1.id },
  );
  // deleted item should no longer be accessible
  await TestValidator.error("deleted item is not accessible", async () => {
    const deleted = await api.functional.shoppingMall.member.carts.items.at(
      memberAConnection,
      { cartId: cartA.id, cartItemId: cartAItem1.id },
    );
    typia.assert(deleted);
  });
  // remaining item should still be accessible and unchanged
  const item2After = await api.functional.shoppingMall.member.carts.items.at(
    memberAConnection,
    { cartId: cartA.id, cartItemId: cartAItem2.id },
  );
  typia.assert(item2After);
  TestValidator.equals(
    "remaining item quantity unchanged",
    item2After.quantity,
    item2Before.quantity,
  );
  TestValidator.equals(
    "remaining item subtotal unchanged",
    item2After.subtotalAmount,
    item2Before.subtotalAmount,
  );
  TestValidator.equals(
    "remaining item variant unchanged",
    item2After.shoppingMallProductVariantId,
    item2Before.shoppingMallProductVariantId,
  );
  // derived cart state should be recomputed
  const cartAAfter = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cartA.id },
  );
  typia.assert(cartAAfter);
  TestValidator.equals(
    "derived cart warning recomputed based on remaining items",
    cartAAfter.warning_inventory_insufficient,
    cartAAfter.warning_inventory_insufficient,
  );
  // =====================
  // Scenario 2: ownership enforcement across different members
  // =====================
  const memberBConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IShoppingMallMember.IJoin,
  });
  const cartB = await generate_random_shopping_mall_member_carts_create(
    memberBConnection,
    {},
  );
  typia.assert(cartB);
  const cartA2Item =
    await generate_random_shopping_mall_member_carts_items_create(
      memberAConnection,
      { params: { cartId: cartA.id } },
    );
  typia.assert(cartA2Item);
  const cartA2Before = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cartA.id },
  );
  typia.assert(cartA2Before);
  const cartBBefore = await api.functional.shoppingMall.member.carts.at(
    memberBConnection,
    { cartId: cartB.id },
  );
  typia.assert(cartBBefore);
  await TestValidator.error(
    "member B cannot delete member A cart item",
    async () => {
      await api.functional.shoppingMall.member.carts.items.erase(
        memberBConnection,
        { cartId: cartA.id, cartItemId: cartA2Item.id },
      );
    },
  );
  const cartA2After = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cartA.id },
  );
  typia.assert(cartA2After);
  const cartA2ItemStill =
    await api.functional.shoppingMall.member.carts.items.at(memberAConnection, {
      cartId: cartA.id,
      cartItemId: cartA2Item.id,
    });
  typia.assert(cartA2ItemStill);
  TestValidator.equals(
    "member A cart warning unchanged after rejected delete",
    cartA2After.warning_inventory_insufficient,
    cartA2Before.warning_inventory_insufficient,
  );
  const cartBAfter = await api.functional.shoppingMall.member.carts.at(
    memberBConnection,
    { cartId: cartB.id },
  );
  typia.assert(cartBAfter);
  TestValidator.equals(
    "member B cart warning unchanged",
    cartBAfter.warning_inventory_insufficient,
    cartBBefore.warning_inventory_insufficient,
  );
  // =====================
  // Scenario 3: cartItemId does not belong to the given cart
  // =====================
  const cart1 = await generate_random_shopping_mall_member_carts_create(
    memberAConnection,
    {},
  );
  typia.assert(cart1);
  const cart2 = await generate_random_shopping_mall_member_carts_create(
    memberAConnection,
    {},
  );
  typia.assert(cart2);
  const itemFromCart1 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberAConnection,
      { params: { cartId: cart1.id } },
    );
  typia.assert(itemFromCart1);
  const itemFromCart2 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberAConnection,
      { params: { cartId: cart2.id } },
    );
  typia.assert(itemFromCart2);
  const cart1Before = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cart1.id },
  );
  typia.assert(cart1Before);
  const cart2Before = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cart2.id },
  );
  typia.assert(cart2Before);
  await TestValidator.error(
    "cannot delete item not belonging to the cart",
    async () => {
      await api.functional.shoppingMall.member.carts.items.erase(
        memberAConnection,
        { cartId: cart1.id, cartItemId: itemFromCart2.id },
      );
    },
  );
  const cart1After = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cart1.id },
  );
  typia.assert(cart1After);
  const cart2After = await api.functional.shoppingMall.member.carts.at(
    memberAConnection,
    { cartId: cart2.id },
  );
  typia.assert(cart2After);
  const itemFromCart1Still =
    await api.functional.shoppingMall.member.carts.items.at(memberAConnection, {
      cartId: cart1.id,
      cartItemId: itemFromCart1.id,
    });
  typia.assert(itemFromCart1Still);
  const itemFromCart2Still =
    await api.functional.shoppingMall.member.carts.items.at(memberAConnection, {
      cartId: cart2.id,
      cartItemId: itemFromCart2.id,
    });
  typia.assert(itemFromCart2Still);
  TestValidator.equals(
    "cart1 warning unchanged",
    cart1After.warning_inventory_insufficient,
    cart1Before.warning_inventory_insufficient,
  );
  TestValidator.equals(
    "cart2 warning unchanged",
    cart2After.warning_inventory_insufficient,
    cart2Before.warning_inventory_insufficient,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_shopping_mall_member_carts_create } from "../../../generate/generate_random_shopping_mall_member_carts_create";
import { generate_random_shopping_mall_member_carts_items_create } from "../../../generate/generate_random_shopping_mall_member_carts_items_create";
import { prepare_random_shopping_mall_cart } from "../../../prepare/prepare_random_shopping_mall_cart";
import { prepare_random_shopping_mall_cart_item } from "../../../prepare/prepare_random_shopping_mall_cart_item";

export async function test_api_cart_erase_clears_inventory_warning_when_responsible_line_removed(
  connection: api.IConnection,
): Promise<void> {
  // 1) member join
  const memberConnection: api.IConnection = { host: connection.host };
  const member = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IShoppingMallMember.IJoin,
  });
  const memberTokenConnection: api.IConnection = { host: connection.host };
  memberTokenConnection.headers ??= {};
  memberTokenConnection.headers.Authorization = member.token.access;
  // 2) create cart
  const cart = await generate_random_shopping_mall_member_carts_create(
    memberTokenConnection,
    {},
  );
  typia.assert(cart);
  // 3) add two cart items using prepared valid variant IDs
  // We expect that at least one of these quantities can trigger the warning.
  // Strategy: create one low-quantity item and one high-quantity item, then
  // re-fetch cart and select the line that makes the warning present.
  const lowItem = await generate_random_shopping_mall_member_carts_items_create(
    memberTokenConnection,
    {
      params: { cartId: cart.id },
      body: typia.assert<IShoppingMallCartItem.ICreate>({
        shoppingMallProductVariantId:
          typia.random<IShoppingMallCartItem.ICreate["shoppingMallProductVariantId"]>(),
        quantity: 1,
      }),
    },
  );
  typia.assert(lowItem);
  const highItem =
    await generate_random_shopping_mall_member_carts_items_create(
      memberTokenConnection,
      {
        params: { cartId: cart.id },
        body: typia.assert<IShoppingMallCartItem.ICreate>({
          shoppingMallProductVariantId:
            typia.random<IShoppingMallCartItem.ICreate["shoppingMallProductVariantId"]>(),
          quantity: 1000,
        }),
      },
    );
  typia.assert(highItem);
  // 4) verify warning present
  const cartWithWarning = await api.functional.shoppingMall.member.carts.at(
    memberTokenConnection,
    {
      cartId: cart.id,
    },
  );
  typia.assert(cartWithWarning);
  // If warning is not present due to environment/inventory semantics, refresh by
  // adding another high quantity item and re-check.
  if (cartWithWarning.warning_inventory_insufficient !== true) {
    const extraHighItem =
      await generate_random_shopping_mall_member_carts_items_create(
        memberTokenConnection,
        {
          params: { cartId: cart.id },
          body: typia.assert<IShoppingMallCartItem.ICreate>({
            shoppingMallProductVariantId:
              typia.random<IShoppingMallCartItem.ICreate["shoppingMallProductVariantId"]>(),
            quantity: 2000,
          }),
        },
      );
    typia.assert(extraHighItem);
    const cartWithWarning2 = await api.functional.shoppingMall.member.carts.at(
      memberTokenConnection,
      { cartId: cart.id },
    );
    typia.assert(cartWithWarning2);
    TestValidator.equals(
      "inventory warning should be present before erase",
      cartWithWarning2.warning_inventory_insufficient,
      true,
    );
    // Determine responsible item to erase (prefer extraHighItem)
    await api.functional.shoppingMall.member.carts.items.erase(
      memberTokenConnection,
      {
        cartId: cart.id,
        cartItemId: extraHighItem.id,
      },
    );
    const cartAfterErase = await api.functional.shoppingMall.member.carts.at(
      memberTokenConnection,
      {
        cartId: cart.id,
      },
    );
    typia.assert(cartAfterErase);
    TestValidator.equals(
      "inventory warning should be cleared after erase",
      cartAfterErase.warning_inventory_insufficient,
      false,
    );
    return;
  }
  TestValidator.equals(
    "inventory warning should be present before erase",
    cartWithWarning.warning_inventory_insufficient,
    true,
  );
  // 5) erase responsible line: attempt to erase highItem first
  await api.functional.shoppingMall.member.carts.items.erase(
    memberTokenConnection,
    {
      cartId: cart.id,
      cartItemId: highItem.id,
    },
  );
  // 6) verify warning cleared
  const cartAfterErase1 = await api.functional.shoppingMall.member.carts.at(
    memberTokenConnection,
    {
      cartId: cart.id,
    },
  );
  typia.assert(cartAfterErase1);
  if (cartAfterErase1.warning_inventory_insufficient === true) {
    // If warning is still present, then the low item must be the responsible one.
    await api.functional.shoppingMall.member.carts.items.erase(
      memberTokenConnection,
      {
        cartId: cart.id,
        cartItemId: lowItem.id,
      },
    );
    const cartAfterErase2 = await api.functional.shoppingMall.member.carts.at(
      memberTokenConnection,
      { cartId: cart.id },
    );
    typia.assert(cartAfterErase2);
    TestValidator.equals(
      "inventory warning should be cleared after erase",
      cartAfterErase2.warning_inventory_insufficient,
      false,
    );
    return;
  }
  TestValidator.equals(
    "inventory warning should be cleared after erase",
    cartAfterErase1.warning_inventory_insufficient,
    false,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_shopping_mall_member_carts_create } from "../../../generate/generate_random_shopping_mall_member_carts_create";
import { generate_random_shopping_mall_member_carts_items_create } from "../../../generate/generate_random_shopping_mall_member_carts_items_create";
import { prepare_random_shopping_mall_cart } from "../../../prepare/prepare_random_shopping_mall_cart";
import { prepare_random_shopping_mall_cart_item } from "../../../prepare/prepare_random_shopping_mall_cart_item";

export async function test_api_cart_erase_updates_subtotal_only_for_removed_line(
  connection: api.IConnection,
): Promise<void> {
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, { body: undefined });
  const cart = await generate_random_shopping_mall_member_carts_create(
    memberConnection,
    { body: undefined },
  );
  typia.assert(cart);
  const cartItem1 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberConnection,
      {
        params: { cartId: cart.id },
        body: undefined,
      },
    );
  typia.assert(cartItem1);
  const cartItem2 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberConnection,
      {
        params: { cartId: cart.id },
        body: undefined,
      },
    );
  typia.assert(cartItem2);
  const cartItem3 =
    await generate_random_shopping_mall_member_carts_items_create(
      memberConnection,
      {
        params: { cartId: cart.id },
        body: undefined,
      },
    );
  typia.assert(cartItem3);
  const beforeCart = await api.functional.shoppingMall.member.carts.at(
    memberConnection,
    { cartId: cart.id },
  );
  typia.assert(beforeCart);

  const beforeItems = typia.assert(
    beforeCart as unknown as { items: IShoppingMallCartItem[] },
  ).items;

  const beforeItem1 = beforeItems.find(
    (i: IShoppingMallCartItem) => i.id === cartItem1.id,
  );
  const beforeItem2 = beforeItems.find(
    (i: IShoppingMallCartItem) => i.id === cartItem2.id,
  );
  const beforeItem3 = beforeItems.find(
    (i: IShoppingMallCartItem) => i.id === cartItem3.id,
  );
  TestValidator.predicate(
    "cart contains all 3 items before deletion",
    () =>
      beforeItem1 !== undefined &&
      beforeItem2 !== undefined &&
      beforeItem3 !== undefined,
  );

  const removedSubtotal = typia.assert(beforeItem2!).subtotalAmount;
  const beforeSubtotal = beforeItems.reduce(
    (sum: number, i: IShoppingMallCartItem) => sum + i.subtotalAmount,
    0,
  );

  await api.functional.shoppingMall.member.carts.items.erase(memberConnection, {
    cartId: cart.id,
    cartItemId: cartItem2.id,
  });

  const afterCart = await api.functional.shoppingMall.member.carts.at(
    memberConnection,
    { cartId: cart.id },
  );
  typia.assert(afterCart);

  const afterItems = typia.assert(
    afterCart as unknown as { items: IShoppingMallCartItem[] },
  ).items;

  TestValidator.predicate(
    "deleted cart item removed from cart listing",
    () => afterItems.every((i: IShoppingMallCartItem) => i.id !== cartItem2.id),
  );

  const afterItem1 = afterItems.find(
    (i: IShoppingMallCartItem) => i.id === cartItem1.id,
  );
  const afterItem3 = afterItems.find(
    (i: IShoppingMallCartItem) => i.id === cartItem3.id,
  );
  TestValidator.predicate(
    "remaining items still exist after deletion",
    () => afterItem1 !== undefined && afterItem3 !== undefined,
  );
  TestValidator.equals(
    "quantity for item1 unchanged",
    typia.assert(afterItem1!).quantity,
    typia.assert(beforeItem1!).quantity,
  );
  TestValidator.equals(
    "quantity for item3 unchanged",
    typia.assert(afterItem3!).quantity,
    typia.assert(beforeItem3!).quantity,
  );

  const afterSubtotal = afterItems.reduce(
    (sum: number, i: IShoppingMallCartItem) => sum + i.subtotalAmount,
    0,
  );
  TestValidator.equals(
    "cart subtotal reduced by removed line contribution",
    afterSubtotal,
    beforeSubtotal - removedSubtotal,
  );
  TestValidator.equals(
    "cart inventory warning flag remains consistent after deletion",
    afterCart.warning_inventory_insufficient,
    beforeCart.warning_inventory_insufficient,
  );
  await TestValidator.error(
    "deleted cart item cannot be retrieved",
    async () => {
      await api.functional.shoppingMall.member.carts.items.at(
        memberConnection,
        { cartId: cart.id, cartItemId: cartItem2.id },
      );
    },
  );
}

