  const nonExistingOrderItemId: string & tags.Format<"uuid"> =
    (
      globalThis as unknown as {
        __existingOrderItemId?: string & tags.Format<"uuid">;
        __nonExistingOrderItemId?: string & tags.Format<"uuid">;
