export async function test_api_review_snapshot_indices_deterministic_ordering(
  connection: api.IConnection,
): Promise<void> {
  // 1) Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  const email = `admin.${RandomGenerator.alphabets(8)}@example.com`;
  const password = `P@ssw0rd-${RandomGenerator.alphabets(8)}`;
  await authorize_admin_join(adminConnection, {
    body: {
      email,
      password,
    } satisfies IShoppingMallAdmin.IJoin,
  });
  // 2) Find a reviewId with at least 2 snapshot indices by probing candidates.
  // (No review-creation SDK/utilities were provided in the input materials.)
  const candidates = ArrayUtil.repeat(6, () =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  let pickedReviewId: string | undefined;
  let pickedLimit = 2;
  for (const reviewId of candidates) {
    const result =
      await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
        adminConnection,
        {
          reviewId,
          body: {
            page: 1,
            limit: 5,
            sortDirection: "asc",
            includeDeleted: undefined,
          } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
        },
      );
    typia.assert(result);
    if (result.data.length >= 2) {
      pickedReviewId = reviewId;
      pickedLimit = Math.min(5, result.data.length);
      break;
    }
  }
  if (!pickedReviewId) {
    throw new Error(
      "No suitable reviewId with at least 2 snapshot indices found in test environment.",
    );
  }
  // 3) Call asc
  const ascPage =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId: pickedReviewId,
        body: {
          page: 1,
          limit: pickedLimit,
          sortDirection: "asc",
          includeDeleted: undefined,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(ascPage);
  TestValidator.equals("asc current page", ascPage.pagination.current, 1);
  TestValidator.equals("asc limit", ascPage.pagination.limit, pickedLimit);
  TestValidator.predicate(
    "asc records non-negative",
    ascPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "asc pages non-negative",
    ascPage.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "asc data length <= limit",
    ascPage.data.length <= ascPage.pagination.limit,
  );
  const ascSequences = ascPage.data.map((x) => x.snapshotSequence);
  TestValidator.predicate(
    "asc snapshotSequence non-decreasing",
    ascSequences.every((v, i, arr) => i === 0 || arr[i - 1] <= v),
  );
  for (const item of ascPage.data) {
    typia.assert(item);
    TestValidator.equals("reviewId matches", item.reviewId, pickedReviewId);
  }
  // 4) Read-only repeat check (state should not change)
  const ascPageRepeat =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId: pickedReviewId,
        body: {
          page: 1,
          limit: pickedLimit,
          sortDirection: "asc",
          includeDeleted: undefined,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(ascPageRepeat);
  TestValidator.equals(
    "asc repeat snapshotSequence deterministic",
    ascPageRepeat.data.map((x) => x.snapshotSequence),
    ascSequences,
  );
  // 5) Call desc
  const descPage =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId: pickedReviewId,
        body: {
          page: 1,
          limit: pickedLimit,
          sortDirection: "desc",
          includeDeleted: undefined,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(descPage);
  TestValidator.equals("desc current page", descPage.pagination.current, 1);
  TestValidator.equals("desc limit", descPage.pagination.limit, pickedLimit);
  const descSequences = descPage.data.map((x) => x.snapshotSequence);
  TestValidator.predicate(
    "desc snapshotSequence non-increasing",
    descSequences.every((v, i, arr) => i === 0 || arr[i - 1] >= v),
  );
  for (const item of descPage.data) {
    typia.assert(item);
    TestValidator.equals("reviewId matches", item.reviewId, pickedReviewId);
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallReviewSnapshotsIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReviewSnapshotsIndex";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallReviewSnapshotsIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewSnapshotsIndex";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

export async function test_api_review_snapshot_indices_pagination_stable_slicing(
  connection: api.IConnection,
): Promise<void> {
  // 1) Admin join
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(admin);
  // NOTE:
  // We must use an existing reviewId that has enough snapshot events.
  // The scenario description assumes such a reviewId is available in test environment.
  // If not, this test will still validate pagination invariants for whatever data exists.
  const reviewId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const limit = 2 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const sortDirection: IShoppingMallReviewSnapshotsIndex.IRequest["sortDirection"] =
    "asc";
  const includeDeleted = false;
  const reqBase = {
    sortDirection,
    includeDeleted,
  } satisfies Omit<
    IShoppingMallReviewSnapshotsIndex.IRequest,
    "page" | "limit"
  >;
  const page1Response =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId,
        body: {
          ...reqBase,
          page: 1,
          limit,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(page1Response);
  TestValidator.equals(
    "pagination.current should match page 1",
    page1Response.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination.limit should match limit",
    page1Response.pagination.limit,
    limit,
  );
  const records = page1Response.pagination.records;
  const pagesExpected =
    records === 0 ? 0 : Math.ceil(records / (limit as number));
  TestValidator.equals(
    "pagination.pages should be ceiling(records/limit)",
    page1Response.pagination.pages,
    pagesExpected,
  );
  TestValidator.predicate(
    "page1 item count should be <= limit",
    page1Response.data.length <= limit,
  );
  const page1Sequences = page1Response.data.map((x) => x.snapshotSequence);
  const page2Response =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId,
        body: {
          ...reqBase,
          page: 2,
          limit,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(page2Response);
  TestValidator.equals(
    "pagination.current should match page 2",
    page2Response.pagination.current,
    2,
  );
  TestValidator.equals(
    "pagination.limit should match limit on page2",
    page2Response.pagination.limit,
    limit,
  );
  TestValidator.equals(
    "pagination.records should be stable across pages",
    page2Response.pagination.records,
    records,
  );
  TestValidator.predicate(
    "page2 item count should be <= limit",
    page2Response.data.length <= limit,
  );
  const page2Sequences = page2Response.data.map((x) => x.snapshotSequence);
  const overlap = new Set<number>(
    page1Sequences.filter((s) => page2Sequences.includes(s)),
  );
  TestValidator.predicate(
    "no snapshotSequence overlap between page1 and page2",
    overlap.size === 0,
  );
  // Validate deterministic slicing by requesting an additional page=1+page2 items using large limit.
  // If pagination backend is stable, the first (limit*2) items should equal page1 + page2 sequence order.
  const combinedLimit = (limit * 2) as number &
    tags.Type<"int32"> &
    tags.Minimum<1>;
  const combinedResponse =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId,
        body: {
          ...reqBase,
          page: 1,
          limit: combinedLimit,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(combinedResponse);
  const combinedSequences = combinedResponse.data.map(
    (x) => x.snapshotSequence,
  );
  const expectedCombinedSlice = page1Sequences.concat(page2Sequences);
  TestValidator.equals(
    "combined first slice should equal concatenation of page1 and page2 sequences",
    combinedSequences.slice(0, expectedCombinedSlice.length),
    expectedCombinedSlice,
  );
  // Edge cases
  if (records !== 0 && records <= limit) {
    TestValidator.equals(
      "when records <= limit, page1 should contain all records",
      page1Response.data.length,
      records,
    );
    TestValidator.equals(
      "when records <= limit, pages should be 1",
      page1Response.pagination.pages,
      1,
    );
  }
  if (records === (limit as number) + 1) {
    TestValidator.equals(
      "when records == limit + 1, page2 should contain exactly 1 item",
      page2Response.data.length,
      1,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallReviewSnapshotsIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReviewSnapshotsIndex";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallReviewSnapshotsIndex } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewSnapshotsIndex";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

export async function test_api_review_snapshot_indices_include_deleted_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1) Admin authorization
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: typia.random<IShoppingMallAdmin.IJoin>(),
  });
  // 2) Find a reachable reviewId (best-effort)
  // We don't have APIs here to create/list reviews, so we probe UUIDs.
  const maxAttempts: number = 10;
  let reviewId: string | undefined = undefined;
  let pageFalse: IPageIShoppingMallReviewSnapshotsIndex.ISummary | undefined =
    undefined;
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const candidate = typia.random<string & tags.Format<"uuid">>();
    try {
      const response =
        await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
          adminConnection,
          {
            reviewId: candidate,
            body: {
              page: 1,
              limit: 50,
              sortDirection: "asc",
              includeDeleted: false,
            } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
          },
        );
      typia.assert(response);
      reviewId = candidate;
      pageFalse = response;
      break;
    } catch (e) {
      // Retry with another uuid. If all attempts fail, rethrow last error.
      if (attempt + 1 >= maxAttempts) throw e;
    }
  }
  if (!reviewId || !pageFalse) {
    throw new Error("Failed to acquire a reachable reviewId for the test.");
  }
  // 4) Validate includeDeleted=false
  const recordsFalse = pageFalse.pagination.records;
  const pagesFalse = pageFalse.pagination.pages;
  TestValidator.equals(
    "includeDeleted=false records match returned data length",
    pageFalse.data.length,
    recordsFalse,
  );
  TestValidator.equals(
    "includeDeleted=false current page",
    pageFalse.pagination.current,
    1,
  );
  if (recordsFalse === 0) {
    TestValidator.equals("includeDeleted=false pages is 0", pagesFalse, 0);
    TestValidator.equals(
      "includeDeleted=false data empty",
      pageFalse.data.length,
      0,
    );
  } else {
    // Every returned item has deletedAt = null
    for (const item of pageFalse.data) {
      TestValidator.equals(
        "deletedAt is null for includeDeleted=false",
        item.deletedAt,
        null,
      );
    }
  }
  const snapshotSequencesFalse = new Set<number>(
    pageFalse.data.map((x) => x.snapshotSequence),
  );
  // 5) Call again with includeDeleted=true
  const pageTrue =
    await api.functional.shoppingMall.admin.reviews.snapshot_indices.index(
      adminConnection,
      {
        reviewId,
        body: {
          page: 1,
          limit: 50,
          sortDirection: "asc",
          includeDeleted: true,
        } satisfies IShoppingMallReviewSnapshotsIndex.IRequest,
      },
    );
  typia.assert(pageTrue);
  // 6) Validate includeDeleted=true superset behavior
  TestValidator.predicate(
    "includeDeleted=true pagination.records >= includeDeleted=false pagination.records",
    pageTrue.pagination.records >= recordsFalse,
  );
  const snapshotSequencesTrue = new Set<number>(
    pageTrue.data.map((x) => x.snapshotSequence),
  );
  for (const seq of snapshotSequencesFalse) {
    TestValidator.predicate(
      "includeDeleted=true snapshotSequence superset",
      snapshotSequencesTrue.has(seq),
    );
  }
  // If includeDeleted=false had data, then includeDeleted=true must not drop any of them.
  // deletedAt can be null or non-null depending on underlying data.
  // If there are no deleted events at all, the responses should match for non-deleted items.
  const hasDeletedTrue = pageTrue.data.some((x) => x.deletedAt !== null);
  const hasDeletedFalse = pageFalse.data.some((x) => x.deletedAt !== null);
  TestValidator.equals(
    "includeDeleted=false contains only non-deleted",
    hasDeletedFalse,
    false,
  );
  if (!hasDeletedTrue) {
    // Expect exact match for deletedAt-null subset (actionType/snapshotSequence)
    TestValidator.equals(
      "includeDeleted=true data length equals includeDeleted=false data length when no deleted events exist",
      pageTrue.data.length,
      pageFalse.data.length,
    );
    TestValidator.equals(
      "includeDeleted=true pagination.records equals includeDeleted=false pagination.records when no deleted events exist",
      pageTrue.pagination.records,
      recordsFalse,
    );
    for (let i = 0; i < pageTrue.data.length; i++) {
      TestValidator.equals(
        "snapshotSequence matches at each index",
        pageTrue.data[i].snapshotSequence,
        pageFalse.data[i].snapshotSequence,
      );
      TestValidator.equals(
        "actionType matches at each index",
        pageTrue.data[i].actionType,
        pageFalse.data[i].actionType,
      );
      TestValidator.equals(
        "deletedAt remains null for includeDeleted=true when no deleted events exist",
        pageTrue.data[i].deletedAt,
        null,
      );
    }
  } else {
    // When deleted events exist, at least one returned item should have deletedAt != null
    TestValidator.predicate(
      "includeDeleted=true includes logically deleted events when they exist",
      hasDeletedTrue,
    );
  }
}

