  typia.assert(got1After);
  TestValidator.equals(
    "recipientName unchanged",
    got1After.recipientName,
    got1.recipientName,
  );
  TestValidator.equals(
    "phoneNumber unchanged",
    got1After.phoneNumber,
    got1.phoneNumber,
  );
  TestValidator.equals(
    "streetLine1 unchanged",
    got1After.streetLine1,
    got1.streetLine1,
  );
  TestValidator.equals(
    "streetLine2 unchanged",
