          ),
        }
      : undefined;
    return {
      id,
      created_at: now,
      updated_at: now,
      deleted_at: null,
      member: {
        connect: { id: props.shoppingMallMembers.id },
      },
      items,
    } satisfies Prisma.shopping_mall_wishlistsCreateInput;
  }
}

