import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAdminAdminPasswordResetsRedeem(props: {
  admin: AdminPayload;
  body: IShoppingMallAdminPasswordReset;
}): Promise<IShoppingMallAdmin> {
  const nowIso = toISOStringSafe(new Date());
  const genericForbidden = (): never => {
    throw new HttpException("Invalid token", 403);
  };
  const reset =
    await MyGlobal.prisma.shopping_mall_admin_password_resets.findUnique({
      where: { token: props.body.token },
      select: {
        id: true,
        shopping_mall_admins_id: true,
        expires_at: true,
        deleted_at: true,
      },
    });
  if (reset === null) {
    genericForbidden();
  }
  // After genericForbidden(), TS still may not narrow; assert with control-flow.
  const safeReset = reset as NonNullable<typeof reset>;
  if (safeReset.deleted_at !== null) {
    genericForbidden();
  }
  if (toISOStringSafe(safeReset.expires_at) <= nowIso) {
    genericForbidden();
  }
  const hashedPassword = await PasswordUtil.hash(props.body.password);
  await MyGlobal.prisma.$transaction(async (tx) => {
    const updatedReset =
      await tx.shopping_mall_admin_password_resets.updateMany({
        where: {
          id: safeReset.id,
          deleted_at: null,
          token: props.body.token,
          expires_at: { gt: new Date(nowIso) },
        },
        data: {
          deleted_at: new Date(nowIso),
          updated_at: new Date(nowIso),
        },
      });
    if (updatedReset.count !== 1) {
      genericForbidden();
    }
    await tx.shopping_mall_admins.update({
      where: { id: safeReset.shopping_mall_admins_id },
      data: {
        password_hash: hashedPassword,
        updated_at: new Date(nowIso),
      },
    });
  });
  const redeemed = await MyGlobal.prisma.shopping_mall_admins.findUniqueOrThrow(
    {
      where: { id: safeReset.shopping_mall_admins_id },
      select: {
        id: true,
        email: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    },
  );
  return {
    id: redeemed.id,
    email: redeemed.email,
    created_at: toISOStringSafe(redeemed.created_at),
    updated_at: toISOStringSafe(redeemed.updated_at),
    deleted_at:
      redeemed.deleted_at === null
        ? null
        : toISOStringSafe(redeemed.deleted_at),
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthAdminRefresh(props: {
  body: IShoppingMallAdmin.IRefresh;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  const { refreshToken } = props.body;
  let decoded: {
    type: "admin";
    id: string;
    session_id: string;
  };
  try {
    decoded = jwt.verify(refreshToken, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as any;
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "admin") throw new HttpException("Forbidden", 403);
  const nowIso = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_admin_sessions.findFirstOrThrow({
    where: {
      id: decoded.session_id,
      shopping_mall_admin_id: decoded.id,
      deleted_at: null,
      expired_at: { gt: nowIso },
    },
    select: {
      id: true,
      shopping_mall_admin_id: true,
      expired_at: true,
    },
  });
  const admin = await MyGlobal.prisma.shopping_mall_admins.findUniqueOrThrow({
    where: { id: decoded.id },
    select: {
      id: true,
      email: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  if (admin.deleted_at !== null) throw new HttpException("Forbidden", 403);
  const createdAtIso = toISOStringSafe(new Date());
  const accessExpIso = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshableIso = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const access = jwt.sign(
    {
      type: "admin",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { issuer: "autobe", expiresIn: "1h" },
  );
  const refresh = jwt.sign(
    {
      type: "admin",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { issuer: "autobe", expiresIn: "7d" },
  );
  await MyGlobal.prisma.shopping_mall_admin_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshableIso, updated_at: nowIso },
  });
  return {
    id: admin.id,
    email: admin.email,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    deleted_at: admin.deleted_at ? toISOStringSafe(admin.deleted_at) : null,
    token: {
      access,
      refresh,
      expired_at: accessExpIso,
      refreshable_until: refreshableIso,
    },
  };
}

