@Controller("/shoppingMall/auth/member")
export class ShoppingmallAuthMemberController {
  /**
   * This endpoint registers a new **member** account as the entry point of the member authentication flow.
   *
   * For the member actor, authorization is performed through JWT-based sessions stored in the database-backed session tables. The join operation corresponds to the Authorization Operations Table row for authorizationType = `join`, and must accept the payload defined by the request DTO type **IShoppingMallMember.IJoin**. On success, it returns the authentication result defined by the response DTO type **IShoppingMallMember.IAuthorized**.
   *
   * This operation is designed to integrate with the subsequent login and refresh operations: once the account exists, the client can also authenticate via **POST /auth/member/login** or renew tokens via **POST /auth/member/refresh** without re-registering.
   *
   * Security-wise, credential material in IShoppingMallMember.IJoin must be handled securely (e.g., password hashing where applicable) and the endpoint must not leak whether an account exists beyond what IShoppingMallMember.IAuthorized and the standard error contract allow.
   *
   * Error handling should return clear client-safe errors for invalid payloads (400) and conflicts such as already-registered identifiers (409).
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Registration payload for creating a new member account.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implement POST /auth/member/join to create a member account. Validate request credentials per IShoppingMallMember.IJoin constraints, create a shopping_mall_members record, and if schema supports email verification/session linking, perform that; otherwise return IShoppingMallMember.IAuthorized containing tokens as defined by the DTO. Use a transaction to ensure atomic creation. Return 201/200 with tokens on success; return 400 for validation errors and 409 for conflicts (e.g., duplicate email/username) per standard. No prerequisites because this is self-contained account registration.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallMember.IJoin,
  ): Promise<IShoppingMallMember.IAuthorized> {
    try {
      return await postShoppingMallAuthMemberJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * This endpoint authenticates a **member** account using login credentials.
   *
   * For the member actor, login is required to establish an authenticated session and produce JWT tokens. The operation corresponds to the Authorization Operations Table row with authorizationType = `login`, accepting the request DTO **IShoppingMallMember.ILogin** and returning **IShoppingMallMember.IAuthorized**.
   *
   * The returned IShoppingMallMember.IAuthorized is the basis for authorization of all member-only business operations. After login, the client can renew tokens by calling **POST /auth/member/refresh**.
   *
   * Security considerations: the endpoint must validate credentials securely, avoid timing leaks as much as possible, and ensure any session token issuance is tied to the authenticated member identity referenced by the data model behind IShoppingMallMember.IAuthorized.
   *
   * Error handling should distinguish invalid credentials (401) from malformed requests (400). If the member account state disallows login (e.g., banned/suspended), respond with an authorization-appropriate error (e.g., 403) while keeping error details minimal.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Login payload containing the member's credentials.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implement POST /auth/member/login to authenticate an existing member account. Validate credentials from IShoppingMallMember.ILogin, verify against shopping_mall_members (and any admin/member password hash fields if present), then create or update a member session record in shopping_mall_member_sessions and/or shopping_mall_guest_sessions only as applicable. Return IShoppingMallMember.IAuthorized with JWT/session tokens. Use rate-limiting hooks if available. Return 200 on success; 401 on wrong credentials; 403 if the member account is banned/suspended per business rules if such fields exist in schema (only if present).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallMember.ILogin,
  ): Promise<IShoppingMallMember.IAuthorized> {
