  public async updateProfile(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IShoppingMallMember.IUpdate,
  ): Promise<IShoppingMallMember> {
    try {
      return await putShoppingMallMemberProfile({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

