   */
  @TypedRoute.Get(":snapshotId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("snapshotId")
    snapshotId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallSnapshot> {
    try {
      return await getShoppingMallMemberSnapshotsSnapshotId({
        member,
        snapshotId,
      });
