  public async lookupByCode(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IShoppingMallSnapshot.IRequest,
  ): Promise<IShoppingMallSnapshot> {
    try {
      return await patchShoppingMallMemberSnapshotsLookupByCode({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

