import { TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia from "typia";

import { IShoppingMallCart } from "../../../../../api/structures/IShoppingMallCart";
import { MemberAuth } from "../../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../../decorators/payload/MemberPayload";
import { getShoppingMallMemberCartWarnings } from "../../../../../providers/getShoppingMallMemberCartWarnings";

@Controller("/shoppingMall/member/cart/warnings")
export class ShoppingmallMemberCartWarningsController {
  /**
   * Retrieve the current warning information for the authenticated customer's cart.
   *
   * This endpoint returns, for the member's own cart, the availability and warning status derived from the latest known variant and inventory data. Cart-level state is represented in `shopping_mall_carts.warning_inventory_insufficient`, while line-level warning/unavailability behavior is driven by how `shopping_mall_cart_items` relate to `shopping_mall_product_variants` and by the inventory availability that is derived from `shopping_mall_inventory_records`.
   *
   * If a cart item quantity exceeds the variant’s current available stock, the response must include the appropriate “exceed-stock” warning context for that cart item. If the referenced product variant is out of stock or unavailable due to deletion/inactivation, the response must mark the cart item as not eligible for checkout. These behaviors must remain consistent with the rule that removal must succeed even if an item becomes unavailable between cart display and removal, and that totals/warnings must be recalculated to reflect the cart’s latest item set.
   *
   * Security and authorization are strict: when the customer is not logged in, cart operations (including viewing cart contents and warnings) are rejected, and if a customer session is missing or invalid the system must not reveal cart contents and must treat the request as unauthorized.
   *
   * Returned data is intended to be used by the client to show warning indicators and prevent checkout of unavailable items. For creating/updating cart items and for recalculating warning state during those mutations, clients should use the cart item update endpoints; this endpoint is a read-only “at-a-glance” warning view.
   *
   * Expected behavior and error handling:
   * - If the authenticated member has no active cart record, the server returns an empty warning list (or cart warning payload with no items) consistent with the customer owning cart relationship.
   * - If inventory has changed since the cart was last displayed or modified, the response must reflect current availability for each cart item based on the latest inventory records.
   * - If the cart itself is marked with `warning_inventory_insufficient`, the response must still include per-item warning/unavailability details consistent with current availability rules.
   *
   * @param connection
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1) Authentication/authorization gate
   * - Require authenticated member context.
   * - Use member identity to locate the owned cart via `shopping_mall_carts.shopping_mall_member_id`.
   * - If session is missing/invalid or caller is not authorized, deny without revealing cart details.
   *
   * 2) Load cart and items
   * - Fetch the cart row (if any) from `shopping_mall_carts`.
   * - Fetch cart items from `shopping_mall_cart_items` filtered by `shopping_mall_cart_id`.
   *
   * 3) Resolve current variant/inventory availability
   * - For each cart item, load `shopping_mall_product_variants` by `shopping_mall_product_variant_id`.
   * - Determine current available stock using `shopping_mall_inventory_records` for the variant. Prefer the latest record by `created_at` (and ignore records soft-deleted by `deleted_at` when present).
   * - Compute:
   *   - `currentAvailableQuantity` = latest available/derived availability from `shopping_mall_inventory_records.available_quantity` (and/or availability logic consistent with domain rules).
   *   - `isVariantActive` = `shopping_mall_product_variants.is_active` and `deleted_at` is null.
   *   - `isCartItemUnavailable` when variant is not active or its current available quantity is zero or otherwise indicates out-of-stock/unavailable.
   *   - `isQuantityExceedStock` when cart item `quantity` > current available quantity.
   *
   * 4) Consistency with persisted cart-level warning
   * - If `shopping_mall_carts.warning_inventory_insufficient` is true, ensure at least one item in the computed result indicates exceed-stock or unavailability; otherwise recompute item warnings from current inventory.
   * - Always ensure totals/warnings remain aligned with “what can actually be purchased”, meaning unavailable items are flagged even if quantity warnings exist.
   *
   * 5) Response assembly
   * - Return a cart warning payload containing:
   *   - cart id (if cart exists),
   *   - cart-level warning boolean derived from recomputation (or reflect stored `warning_inventory_insufficient` but must match item calculations),
   *   - an array of per-cart-item warning entries including cart item id, product variant id, quantity, current available quantity, and flags for exceed-stock warning and eligibility/unavailability.
   *
   * 6) Edge cases
   * - No cart row: return empty warning entries.
   * - Variants deleted/inactive between last update and now: mark items unavailable while still allowing removal per business rule (the warning view must reflect the current status).
   * - Inventory records missing for a variant: treat available quantity as zero and mark items unavailable; include an explanatory warning category per DTO.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async atCartWarnings(
    @MemberAuth()
    member: MemberPayload,
  ): Promise<IShoppingMallCart> {
    try {
      return await getShoppingMallMemberCartWarnings({
        member,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia from "typia";

import { IShoppingMallCart } from "../../../../../../api/structures/IShoppingMallCart";
import { MemberAuth } from "../../../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../../../decorators/payload/MemberPayload";
import { patchShoppingMallMemberCartWarningsRefresh } from "../../../../../../providers/patchShoppingMallMemberCartWarningsRefresh";

@Controller("/shoppingMall/member/cart/warnings/refresh")
export class ShoppingmallMemberCartWarningsRefreshController {
  /**
   * Refreshes a member’s cart warning state by re-validating each cart item against the current availability of its referenced product variant.
   *
   * This operation addresses the business requirements where cart items must display an exceed-stock warning when the item quantity is greater than the variant’s current available stock, and where an item must be marked unavailable when its variant is out of stock or unavailable (e.g., deleted/disabled). The cart container maintains a cart-level boolean flag (shopping_mall_carts.warning_inventory_insufficient) representing whether at least one cart item currently has inventory insufficiency issues.
   *
   * The cart line items (shopping_mall_cart_items) store quantity and subtotal_amount captured when stored, while the variant stock/availability is derived from immutable inventory history (shopping_mall_inventory_records) and the variant’s enabled/deleted status (shopping_mall_product_variants.deleted_at and shopping_mall_product_variants.is_active). During this refresh, the system must update each cart item’s displayed eligibility/warning context so there is no stale availability information.
   *
   * This endpoint is intended to be used when the frontend needs to re-check cart warnings after quantity edits or after inventory changes that can occur independently of the cart. It keeps cart totals and warning indicators internally consistent: any availability change must not leave totals/warnings mismatched with the updated set of orderable items.
   *
   * Authorization: only an authenticated member who owns the target cart must be able to refresh it. Guests and other members must not be able to access carts they do not own.
   *
   * Error handling and edge cases:
   * - If the cart does not exist or is not owned by the caller, the operation should fail with an appropriate authorization/not-found error.
   * - If some cart items reference variants that are now out of stock or have been deleted/disabled, those items must become unavailable and supersede any exceed-stock warning context.
   * - If the cart is concurrently modified, the server should perform the refresh using a transaction and compute results from the latest persisted cart items and the current inventory state.
   *
   * Related operations:
   * - Cart item quantity update operations must already re-validate availability and warnings on each update; this endpoint provides an additional explicit refresh when needed.
   * - Cart viewing operations should reflect the latest warning_inventory_insufficient and item-level warning/unavailable context computed by this refresh.
   *
   * @param connection
   * @param body Refresh criteria identifying which cart should be re-validated for inventory warnings. The server recomputes warnings and unavailability indicators from current variant inventory state.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1) Input parsing: Read refresh request fields to identify the target cart (e.g., cartId). Validate that cartId is a UUID.
   *
   * 2) Authorization & ownership: Verify the authenticated member owns shopping_mall_carts.id == cartId.
   *
   * 3) Load cart and active cart items:
   * - SELECT shopping_mall_carts by id.
   * - SELECT shopping_mall_cart_items for that cart where deleted_at IS NULL.
   *
   * 4) For all distinct shopping_mall_product_variant_id in the cart items:
   * - Load current variant status from shopping_mall_product_variants: deleted_at (null check) and is_active.
   * - Derive current available quantity from the latest shopping_mall_inventory_records row per variant (use created_at ordering). Compute availability = available_quantity from that record (and respect any disabled/unavailable state from the variant row).
   *
   * 5) Recompute per cart item:
   * - If variant is deleted (shopping_mall_product_variants.deleted_at IS NOT NULL) OR is_active == false OR available_quantity <= 0:
   *   - Mark the cart item as unavailable for checkout (unavailable flag is represented in the API DTO computed from these states; if persistence exists for availability in cart item, update it accordingly).
   *   - Item unavailable status must supersede exceed-stock warning context.
   * - Else if cart item quantity > available_quantity:
   *   - Set cart item warning context to “exceeds stock”.
   * - Else:
   *   - Clear exceed-stock warning context for that item.
   *
   * 6) Recompute cart-level flag:
   * - Set shopping_mall_carts.warning_inventory_insufficient to true if any active cart item is in an exceed-stock warning state (and/or if business defines it for insufficiency). Ensure it matches the computed per-item context.
   *
   * 7) Consistency with totals:
   * - Ensure cart totals returned by the response are computed from the current cart item set and their stored subtotal_amount (and/or recomputed if subtotal_amount is derived during item update). At minimum, do not return totals that contradict the updated warning/unavailability indicators.
   *
   * 8) Persist updates in a transaction:
   * - UPDATE shopping_mall_carts.warning_inventory_insufficient.
   * - If any cart item table has persistable warning/unavailable columns in this schema version, UPDATE them; otherwise, ensure the DTO layer returns computed states.
   *
   * 9) Return refreshed cart representation (summary) including item-level warning/unavailable indicators and cart-level warning_inventory_insufficient.
   *
   * Edge cases:
   * - If the cart becomes empty after excluding deleted cart items, set warning_inventory_insufficient=false.
   * - If inventory records are missing for a variant, treat it as unavailable and mark items unavailable (fail-safe) so checkout restrictions are respected.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async refreshCartWarnings(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IShoppingMallCart.IRequest,
  ): Promise<IShoppingMallCart.ISummary> {
    try {
      return await patchShoppingMallMemberCartWarningsRefresh({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { TypedBody, TypedRoute } from "@nestia/core";
