import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IShoppingMallShipment } from "../../../../../api/structures/IShoppingMallShipment";
import { MemberAuth } from "../../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../../decorators/payload/MemberPayload";
import { getShoppingMallMemberShipmentsShipmentIdTracking } from "../../../../../providers/getShoppingMallMemberShipmentsShipmentIdTracking";

@Controller("/shoppingMall/member/shipments/:shipmentId/tracking")
export class ShoppingmallMemberShipmentsTrackingController {
  /**
   * Retrieve tracking details for a single shipment.
   *
   * This endpoint provides the per-shipment carrier tracking information customers can use to follow fulfillment progress. A shipment is the per-seller fulfillment unit inside an order, so the tracking returned here applies to the shipment as a whole (and therefore to all order items included in that shipment), rather than to individual items.
   *
   * The tracking fields are sourced from the seller confirmation record associated with the shipment. When confirmation tracking details are missing, the endpoint must not invent values; it should return the tracking fields as unavailable/empty according to the response DTO. Visibility is restricted so that customers can only retrieve tracking for shipments that belong to their orders, and administrators can view tracking through order oversight without modifying shipment tracking.
   *
   * This operation depends on the order-detail views and shipment creation workflow:
   * - Customers typically reach this endpoint from the order details page, where the system lists shipments belonging to the order.
   * - Shipment tracking data displayed here is created at shipment confirmation time; this endpoint is read-only for display and does not perform any state transitions.
   *
   * Expected behavior:
   * - If the shipment does not belong to the logged-in customer (or is not visible in the caller’s context), respond with 404.
   * - If a shipment exists but has no associated confirmation record, respond with unavailable/empty tracking fields.
   *
   * @param connection
   * @param shipmentId Target shipment ID (UUID) whose tracking details should be retrieved.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implement a read-only endpoint that returns tracking metadata for one shipment.
   *
   * Algorithm / service steps:
   * 1. Validate and parse `shipmentId` as UUID.
   * 2. Query `shopping_mall_shipments` by `id = shipmentId` and ensure the shipment record is not hidden from active views by checking `deleted_at` is null.
   * 3. Load the associated seller confirmation record through `shopping_mall_shipment_confirmations` using `shopping_mall_shipments.id` => `shopping_mall_shipment_confirmations.shopping_mall_shipment_id`.
   *    - The relation is optional, so if the confirmation record does not exist, return a response indicating tracking is unavailable (do not return invented values).
